runtime/kernel_selector.cpp: added gating helper
+ bool KernelSelector::isFastpathAllowed(const ModelMeta& meta) {
+   if (config.safe_mode) return false;
+   if (!meta.has_kv_cache) return false;
+   if (meta.head_dim % 8 != 0) return false; // misaligned head dims degrade fp16
+   return true;
+ }

